const fetch = require('node-fetch');

async function mintNFT() {
  // Bug 1: Using client-side API key (ck_) instead of server-side (sk_)
  const apiKey = 'ck_test_51HxXxXxXxXxXxXxXxXxXxXxXxXxXxXxXxXxXxXxX';

  // Bug 2: Malformed recipient format using pipe separators
  const recipient = 'email|user@example.com|polygon-amoy';

  // Bug 3: Missing required 'image' field in metadata
  const metadata = {
    name: 'My NFT',
    description: 'A test NFT minted via Crossmint'
  };

  // Bug 4: Wrong API base URL
  const baseUrl = 'https://crossmint.com/api/';

  try {
    const response = await fetch(`${baseUrl}2022-06-09/collections/default/nfts`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-API-KEY': apiKey
      },
      body: JSON.stringify({
        recipient: recipient,
        metadata: metadata
      })
    });

    const data = await response.json();

    // Write response to file
    const fs = require('fs');
    fs.writeFileSync('/home/user/fixed_mint_response.json', JSON.stringify(data, null, 2));

    console.log('Mint response:', data);
    return data;
  } catch (error) {
    console.error('Error minting NFT:', error);
    const fs = require('fs');
    fs.writeFileSync('/home/user/fixed_mint_response.json', JSON.stringify({ error: error.message }, null, 2));
    throw error;
  }
}

mintNFT();

